package com.example.studentactivity; import android.content.Intent; import android.os.Bundle; import android.view.View; import android.widget.CheckBox; import android.widget.EditText; import android.widget.RadioButton; import android.widget.RadioGroup; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { EditText etName,etPhone; RadioGroup rgDept,rgGender; CheckBox cbInputAI,cbInputCloud,cbInputShip,cbInputAutocad; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etName=findViewById(R.id.name);etPhone=findViewById(R.id.phone);rgDept=findViewById(R.id.radioGroupDept);rgGender=findViewById(R.id.radioGroupGender);cbInputAI=findViewById(R.id.cbAI);cbInputCloud=findViewById(R.id.cbCloud);cbInputShip=findViewById(R.id.cbShip);cbInputAutocad=findViewById(R.id.cbAuto);} public void insert(View v){String name=etName.getText().toString().trim(),phone=etPhone.getText().toString().trim();if(name.isEmpty()){etName.setError("Enter your name");return;}if(phone.length()!=10){etPhone.setError("Enter a valid 10-digit phone number");return;}int d=rgDept.getCheckedRadioButtonId(),g=rgGender.getCheckedRadioButtonId();if(d==-1){Toast.makeText(this,"Please select a department",Toast.LENGTH_SHORT).show();return;}if(g==-1){Toast.makeText(this,"Please select a gender",Toast.LENGTH_SHORT).show();return;}String dept=((RadioButton)findViewById(d)).getText().toString(),gender=((RadioButton)findViewById(g)).getText().toString();StringBuilder courses=new StringBuilder();if(cbInputAI.isChecked())courses.append(cbInputAI.getText()).append(", ");if(cbInputCloud.isChecked())courses.append(cbInputCloud.getText()).append(", ");if(cbInputShip.isChecked())courses.append(cbInputShip.getText()).append(", ");if(cbInputAutocad.isChecked())courses.append(cbInputAutocad.getText()).append(", ");if(courses.length()==0)courses.append("None");else courses.setLength(courses.length()-2);Intent i=new Intent(this,SecondaryActivity.class);i.putExtra("name",name);i.putExtra("phone",phone);i.putExtra("department",dept);i.putExtra("gender",gender);i.putExtra("courses",courses.toString());startActivity(i);}}
